<script setup>
import { onUnmounted, reactive, watch } from 'vue'
import { createCompatibilityStore, reasonCount, releaseLabel, candidateSummary } from './compatibilityStore.js'
const props = defineProps({ bridge: { type: Object, required: true }, profile: { type: Object, default: null }, selectedReleaseIds: { type: Array, default: () => [] }, disabled: Boolean, hideCheckButton: Boolean })
const state = reactive({}), store = createCompatibilityStore(props.bridge, state)
watch(() => [props.profile?.profile_id, props.profile?.revision], () => store.setProfile(props.profile), { immediate: true })
const category = value => ({ dependency: '依赖与能力', file: '文件与归属', runtime: '运行交互' })[value] || '其他信息'
const severity = value => ({ blocker: '阻断', warning: '提醒', info: '信息' })[value] || '信息'
const format = value => typeof value === 'string' ? value : JSON.stringify(value, null, 2)
const statusText = () => ({ unchecked: '尚未检查此方案', checking: '正在检查所选 Mod 的依赖和文件冲突…', cancelled: '检查已取消，可以重新检查。', stale: '方案已更改，请重新检查。', error: '检查未完成', ready: state.report?.blocking ? '发现冲突，请查看下方原因。' : '检查完成：未发现确定冲突，未证明运行兼容。' })[state.status]
defineExpose({ check: () => store.check() })
onUnmounted(() => store.dispose())
</script>
<template>
  <section class="compatibility-panel" aria-label="依赖与兼容性检查">
    <div class="actions"><button v-if="!hideCheckButton" data-testid="compatibility-check" :disabled="disabled || state.busy || !profile" @click="store.check()">检查方案</button><button data-testid="compatibility-enable-preview" :disabled="disabled || state.busy || !profile || !selectedReleaseIds.length" @click="store.check('enable',selectedReleaseIds)">预览启用所选</button><button data-testid="compatibility-disable-preview" :disabled="disabled || state.busy || !profile || !selectedReleaseIds.length" @click="store.check('disable',selectedReleaseIds)">预览停用所选</button><button v-if="state.busy && state.task" data-testid="compatibility-cancel" :disabled="state.task.state === 'cancelling'" @click="store.cancel">取消检查</button></div>
    <p data-testid="compatibility-status" :data-state="state.status" role="status" class="check-status">{{ statusText() }}</p><p v-if="state.error" role="alert" class="error-message">{{ state.error }}</p><button v-if="state.status === 'error' || state.status === 'cancelled'" data-testid="compatibility-retry" :disabled="disabled || state.busy || !profile" @click="store.check()">重新检查</button>
    <div v-if="state.report" data-testid="compatibility-report" :data-blocking="state.report.blocking">
      <p class="hint">共 {{ state.report.findings.length }} 项检查提示。以下建议供调整方案时参考。</p><p v-if="!state.report.findings.length" data-testid="compatibility-no-findings">当前方案未发现依赖或文件冲突。游戏内运行情况仍需单独验证。</p>
      <details><summary>检查范围与规则版本</summary><p>规则版本：{{ state.report.rule_version }}</p><pre data-testid="compatibility-scope">{{ format(state.report.scope) }}</pre></details>
      <article v-for="finding in state.report.findings" :key="finding.id" data-testid="compatibility-finding" :data-category="finding.category" :data-severity="finding.severity" :data-code="finding.code"><h4>{{ category(finding.category) }} · {{ severity(finding.severity) }}</h4><p>{{ finding.message }}</p><p v-if="finding.release_ids?.length">受影响版本：{{ finding.release_ids.map(id => releaseLabel(state.report.release_labels,id)).join('、') }}</p><p v-if="finding.detail?.target">文件目标：{{ Array.isArray(finding.detail.target) ? finding.detail.target.join('/') : finding.detail.target }}</p><div class="evidence"><p>来源：{{ typeof finding.source === 'string' ? finding.source : (finding.source?.label || finding.source?.kind || '见来源详情') }}</p><p>原因链：{{ reasonCount(finding.reason_chain) }} 项关联</p><details><summary>查看原因链、来源与适用范围</summary><h5>原因链</h5><pre data-testid="compatibility-reason">{{ format(finding.reason_chain) }}</pre><h5>来源</h5><pre>{{ format(finding.source) }}</pre><h5>指纹与适用范围</h5><pre>{{ format(finding.scope) }}</pre><h5>具体证据（文件、哈希与规则输入）</h5><pre data-testid="compatibility-detail">{{ format(finding.detail) }}</pre><h5>关联记录</h5><pre>{{ format({ component_ids:finding.component_ids,release_ids:finding.release_ids,relation_ids:finding.relation_ids,code:finding.code }) }}</pre></details></div></article>
      <div class="candidate-columns"><section v-if="state.report.enable_preview" data-testid="compatibility-enable-set" :data-release-ids="JSON.stringify(state.report.enable_preview.release_ids)"><h4>启用候选组合</h4><p>完整集合 {{ state.report.enable_preview.release_ids?.length || 0 }} 个版本 · {{ candidateSummary(state.report.enable_preview) }}</p><ul><li v-for="id in state.report.enable_preview.release_ids" :key="id">{{ releaseLabel(state.report.release_labels,id) }}</li></ul><details v-if="state.report.enable_preview.candidate_finding_codes?.length"><summary>候选检查项目</summary><pre>{{ format(state.report.enable_preview.candidate_finding_codes) }}</pre></details><p data-testid="compatibility-added">其中需新增 {{ state.report.enable_preview.added_release_ids?.length || 0 }} 个版本</p><details><summary>查看完整集合和引用链</summary><pre>{{ format(state.report.enable_preview) }}</pre></details></section><section v-if="state.report.disable_preview" data-testid="compatibility-disable-set" :data-release-ids="JSON.stringify(state.report.disable_preview.release_ids)"><h4>停用影响预览</h4><p>完整集合 {{ state.report.disable_preview.release_ids?.length || 0 }} 个版本</p><ul><li v-for="id in state.report.disable_preview.release_ids" :key="id">{{ releaseLabel(state.report.release_labels,id) }}</li></ul><p v-if="state.report.disable_preview.candidate_blocking === true">候选组合仍有阻断。</p><details v-if="state.report.disable_preview.candidate_finding_codes?.length"><summary>候选检查项目</summary><pre>{{ format(state.report.disable_preview.candidate_finding_codes) }}</pre></details><p data-testid="compatibility-affected">受影响 {{ state.report.disable_preview.affected_release_ids?.length || 0 }} 个版本，由你决定是否调整。</p><ul><li v-for="id in state.report.disable_preview.affected_release_ids" :key="id">{{ releaseLabel(state.report.release_labels,id) }}</li></ul><details><summary>查看完整集合和引用链</summary><pre>{{ format(state.report.disable_preview) }}</pre></details></section></div>
      <details v-if="state.report.cycles?.length"><summary>循环关系（{{ state.report.cycles.length }}）</summary><p>循环关系保留，未删除关系或自动调整配置。</p><pre>{{ format(state.report.cycles) }}</pre></details><details v-if="state.report.unknowns?.length"><summary>未知项（{{ state.report.unknowns.length }}）</summary><pre>{{ format(state.report.unknowns) }}</pre></details>
    </div>
  </section>
</template>
<style scoped>
.compatibility-panel{border:1px solid rgb(var(--rgb-border-base)/.2);border-radius:10px;padding:12px;margin:12px 0;background:var(--bg-surface,#1e293b);color:var(--text-main,#f1f5f9)}.actions{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:10px}p{margin:6px 0;line-height:1.6}.hint,.evidence{color:var(--text-dim,#94a3b8)}h4{font-size:13px;margin:6px 0}h5{font-size:12px;margin:8px 0}article{border-top:1px solid rgb(var(--rgb-border-base)/.18);padding:10px 0}details{margin:8px 0}summary{cursor:pointer}.candidate-columns{display:grid;grid-template-columns:1fr 1fr;gap:12px}.candidate-columns>section{border:1px solid rgb(var(--rgb-border-base)/.18);border-radius:8px;padding:10px;min-width:0}pre{background:var(--bg-deep,#0f172a);color:var(--text-main,#f1f5f9);padding:8px;border-radius:6px;white-space:pre-wrap;overflow-wrap:anywhere;max-height:260px;overflow:auto;user-select:text;font-size:11px}.error-message{color:var(--accent-danger,#fb7185)}@media(max-width:700px){.candidate-columns{grid-template-columns:1fr}}
</style>
